# ===== security - الحارس =====
@dataclass
class LoginContext:
    ip_country: str; last_country: str; hours_since_last_login: float; is_new_device: bool; failed_attempts: int
    ip_asn: str = ""; last_asn: str = ""; logins_last_10min: int = 0; sensitive_actions_last_10min: int = 0; distance_km: float = 0.0; is_tor: bool = False; is_datacenter_ip: bool = False
class NoorSecurityAlgorithms:
    @staticmethod
    def calculate_privacy_health_score(settings: Dict) -> Dict:
        score = 100; recs = []
        def penalize(amount, action, title, impact, severity, patch=None):
            nonlocal score; score -= amount; recs.append({"action": action, "title": title, "impact": impact, "severity": severity, "patch": patch or {}, "penalty": amount})
        if not settings.get("two_factor_enabled", False): penalize(30, "ENABLE_2FA", "تفعيل المصادقة الثنائية (2FA)", "+30%", "critical")
        if not settings.get("passkey_count", 0): penalize(10, "ADD_PASSKEY", "أضف Passkey", "+10%", "high")
        if settings.get("default_post_audience") == "PUBLIC": penalize(15, "RESTRICT_AUDIENCE", "تقييد المنشورات للأصدقاء فقط", "+15%", "high")
        if settings.get("app_lock_timeout", 0) == 0: penalize(10, "ENABLE_APP_LOCK", "تفعيل قفل نور شات", "+10%", "medium")
        if settings.get("phone_visibility") == "PUBLIC": penalize(10, "HIDE_PHONE", "رقم تلفونك ظاهر", "+10%", "high")
        if settings.get("active_status", True): penalize(5, "HIDE_ACTIVE_STATUS", "إخفاء حالة النشاط", "+5%", "low")
        if settings.get("message_delivery") == "EVERYONE": penalize(10, "LIMIT_MESSAGES", "قيد الرسائل للأصدقاء", "+10%", "high")
        score = max(0, score); recs = sorted(recs, key=lambda x: x["penalty"], reverse=True)
        return {"privacy_score": score, "status": "ممتاز 🟢" if score >= 85 else ("جيد 🟡" if score >= 70 else ("متوسط 🟠" if score >= 50 else "يحتاج تحسين 🔴")), "total_issues": len(recs), "quick_fixes": recs, "fix_all_patch": {}}
    @staticmethod
    def detect_account_takeover_risk(ctx: LoginContext) -> Dict:
        travel = 1.0 if ctx.ip_country != ctx.last_country and ctx.hours_since_last_login < 2 else 0.3 if ctx.ip_country != ctx.last_country else 0.0
        device = 1.0 if ctx.is_new_device else 0.0
        velocity = min(1.0, ctx.logins_last_10min / 5.0)
        z = (0.25*travel + 0.20*device + 0.15*velocity) * 4 - 1.5
        risk = round(1/(1+math.exp(-z)), 2)
        return {"risk_score": risk, "lock_sensitive_settings": risk>=0.75, "action_required": "BIOMETRIC_OR_PASSKEY_CHALLENGE" if risk>=0.75 else "ALLOW", "message": "دخول آمن" if risk<0.75 else "نشاط غير عادي"}

